"""Publish a bounded sampled-actuator milestone with source downloads."""
import hashlib,json,re,shutil,zipfile
from pathlib import Path
R=Path('/workspace/scratch/1544cec576c6');D=R/'ud-public/dist'
C=R/'ud-repo/captures/2026-10-20T163500Z-codex-sampled-actuator-9c71de42'
names=['UD_SAMPLED_ACTUATOR_THEOREM_v0.1.pdf','UD_SAMPLED_ACTUATOR_THEOREM_v0.1.tex','sampled_actuator_certificate.py','finite_record_certificate_dependency.py','SAMPLED_ACTUATOR_CERTIFICATE_v0.1.json','GAUSS_INTEGRATION_v0.1.json','APPARATUS_COMPONENT_CONTRACT_v0.1.json','requirements.txt','PROVENANCE_v0.1.json','PDF_QA_v0.1.json']
dest=D/'sources/sampled-actuator-v0.1';dest.mkdir(parents=True,exist_ok=True)
for name in names:shutil.copy2(C/name,dest/name)
